assert.deepEqual(parseDotEnv(text), {
  OPENAI_API_KEY: 'plac[REDACTED](18 chars)',
  BROWSER_USE_LLM_MODEL: 'gpt-4o',
  ANTHROPIC_API_KEY: 'plac[REDACTED](21 chars)'
